function sharedService(e,o){function r(e){let r="Config/EmailConfig/",t=JSON.stringify({tipo:2,...e});return showLoader(),o.getData("get",`${r}Get?json=${t}`,null,!0).then(e=>{let o={correos:[],telefonos:[]};if("1"===e.code){let[r]=JSON.parse(e.payload),{correo:t,telefono:i}=r[0];o.correos=t?t.split(/[\|;]/):[],o.telefonos=i?i.split(/[\|;]/):[]}return o}).finally(()=>hideLoader())}return{getDataFormNotificacion:r}}app.factory("sharedService",sharedService),sharedService.$inject=["$injector","mainService"];